sys_script.script:
// Import the progress tracking function
const { updateCourseProgress } = require('../../server/progress-tracking.js');

// Find the student's enrollment for this course
var assessmentGR = new GlideRecord('x_1879300_learning_assessments');
if (assessmentGR.get(current.assessment)) {
    var courseId = '';

    // Get course ID from assessment (either directly or through lesson)
    if (assessmentGR.course) {
        courseId = assessmentGR.getValue('course');
    } else if (assessmentGR.lesson) {
        var lessonGR = new GlideRecord('x_1879300_learning_lessons');
        if (lessonGR.get(assessmentGR.lesson)) {
            courseId = lessonGR.getValue('course');
        }
    }

    if (courseId) {
        // Find student enrollment
        var enrollmentGR = new GlideRecord('x_1879300_learning_student_enrollments');
        enrollmentGR.addQuery('student', current.user);
        enrollmentGR.addQuery('course', courseId);
        enrollmentGR.query();

        if (enrollmentGR.next()) {
            // Update progress
            var result = updateCourseProgress(enrollmentGR.getUniqueValue());
            if (result.success) {
                gs.info('Progress updated for student ' + current.user + ' in course ' + courseId + ': ' + result.progressPercentage + '%');
            }
        }
    }
}
